def open_session(root,path,config,*,ownership_path):
 """Normal scheduler/ingress entry point for the managed lab configuration."""
 a=ManagedAuthority(root,path,config,ownership_path=ownership_path);a.recover()
 return a,a._runtime.Scheduler(a)

def run(candidate, draft, runtime, destination, client, *, create=False):
    """General entry: no control capability, status return or status publication."""
    failed = False
    try:
        launcher = _load_launcher()
    except BaseException:
        failed = True
    if failed:
        _fail()
    return _run(launcher, candidate, draft, runtime, destination, client, create, None)

def run_controlled(candidate, draft, runtime, destination, client, *, control, create=False):
    """Trusted owner entry ONLY; control may consume/capture exact status under
    separate authorization. This callable is not authentication of its caller.
    No capture sink, logger, serializer or retention permission is added here.
    """
    failed = False
    try:
        launcher = _load_launcher()
    except BaseException:
        failed = True
    if failed:
        _fail()
    return _run(launcher, candidate, draft, runtime, destination, client, create, control)

def status(self):
        owner = _OWNERS.get(self.__token)
        if owner is None:
            _fail()
        return owner.wrapper.status()

def _run(launcher, candidate, draft, runtime, destination, client, create, control):
    """Trusted orchestration seam; production callers use run/run_controlled."""
    failed = False
    try:
        with launcher.session(candidate, draft, runtime, destination, create=create) as wrapper:
            owner = _Owner(wrapper); token = object(); _OWNERS[token] = owner
            try:
                if control is not None:
                    control(_Control(token))  # Explicit separately authorized use.
                try:
                    client(Client(token))
                except BaseException as client_error:
                    if owner.failure is not None:
                        raise owner.failure from client_error
                    raise
                if owner.failure is not None:
                    raise owner.failure
            finally:
                # Revoke before close, including failed/uncertain cleanup.
                _OWNERS.pop(token, None)
        # Callback returns are deliberately not forwarded to another recipient.
    except BaseException:
        # Original launcher already handled original failure/cleanup evidence.
        # Do not print it, transform its retained record, or infer nonexecution.
        failed = True
    if failed:
        _fail()

def _dispatch(token, operation, packet):
    owner = _OWNERS.get(token)
    if owner is None or owner.failure is not None:
        _fail()
    try:
        if operation == 'handle':
            if type(packet) is not bytes:
                raise TypeError('PACKET-BYTES')
            result = owner.wrapper.handle(packet)
            if type(result) is not bytes:
                raise TypeError('RESPONSE-BYTES')
            return result  # Preserve exact authenticated response; no re-encoding.
        if operation != 'state':
            raise RuntimeError('CLIENT-OPERATION')
        result = owner.wrapper.state()
        if type(result) is not dict or set(result) != _STATE_KEYS:
            raise RuntimeError('STATE-SHAPE')
        return _data(result)
    except BaseException as error:
        # Keep the ORIGINAL failure for the launcher's existing retention/cleanup
        # path. No new log and no swallowed fault if the client catches failure.
        owner.failure = error
    # Outside the handler: no original engine exception in __context__/__cause__.
    _fail()

def _data(value):
    """Detach only exact JSON value types; never invoke object copy/repr hooks."""
    if type(value) in (str, int, bool, type(None)):
        return value
    if type(value) is list:
        return [_data(v) for v in value]
    if type(value) is dict and all(type(k) is str for k in value):
        return {k: _data(v) for k, v in value.items()}
    raise RuntimeError('UNSUPPORTED-CLIENT-VALUE')

def fixed_status(root,frames):
 tree=ast.parse((Path(root)/SOURCES['manager']).read_bytes())
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='ManagedAuthority')
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 node=methods['status'];returns=[n for n in ast.walk(node) if isinstance(n,ast.Return)]
 need(len(returns)==1 and isinstance(returns[0].value,ast.Dict),'UNSUPPORTED-STATUS-SOURCE')
 fields={ast.literal_eval(k):v for k,v in zip(returns[0].value.keys,returns[0].value.values)}
 dynamic={'self._phase':'phase','self._epoch':'epoch','self._reason':None}
 for f in frames.values():
  if f['call']['function']=='ManagedAuthority.status' and f['normal']:
   ret=f['return']['value'];need(type(ret) is dict and set(ret)==set(fields),'STATUS-FIELDS')
   for key,expr in fields.items():
    if isinstance(expr,ast.Constant):same(ret[key],expr.value,'STATUS-SOURCE-CONSTANT:'+key)
    else:
     selector=ast.unparse(expr);need(selector in dynamic,'UNSUPPORTED-STATUS-EXPRESSION')
     if dynamic[selector] is not None:same(ret[key],f['return']['state'][dynamic[selector]],'STATUS-STATE:'+key)
     else:need(type(ret[key]) is str,'STATUS-REASON-TYPE')
  if f['call']['function']=='ManagedAuthority.recover' and f['normal']:
   statuses=[g for g in frames.values() if g['call']['parent']==f['call']['frame'] and g['call']['function']=='ManagedAuthority.status']
   need(len(statuses)==1 and statuses[0]['normal'],'RECOVERY-STATUS-CALL')
   same(f['return']['value']['status'],statuses[0]['return']['value'],'RECOVERY-STATUS-EDGE')

def __call__(self,f,event,arg):
  if event not in ('call','line','return','exception'):return self
  keys=[k for k,v in self.spec.items() if k[1]==f.f_code.co_qualname and v['code'].co_code==f.f_code.co_code and v['code'].co_firstlineno==f.f_code.co_firstlineno]
  if len(keys)!=1:return self
  key=keys[0]
  if event=='call':self.ids[id(f)]=self.next;self.next+=1
  if id(f) not in self.ids:return self
  p=f.f_back
  while p is not None and id(p) not in self.ids:p=p.f_back
  row={'seq':len(self.events),'frame':self.ids[id(f)],'parent':None if p is None else self.ids[id(p)],'source':key[0],'function':key[1],'event':event,'offset':f.f_lasti,'line':f.f_lineno,'state':snap(f)}
  if event=='call':row['arguments']={k:value(v) for k,v in f.f_locals.items() if k not in ('self','root','path','ownership_path','a')}
  if event=='return':row['value']=value(arg)
  if event=='exception':row['exception']={'type':arg[0].__name__,'message':str(arg[1])}
  self.events.append(row)
